// Build step: bundles the Pro lessons into the API function, so they are never part of the public site.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
const dir = new URL("../pro_lessons/", import.meta.url);
const out = {};
for (const f of readdirSync(dir)) if (f.endsWith(".js")) out[f.replace(/\.js$/, "")] = readFileSync(new URL(f, dir), "utf8");
writeFileSync(new URL("../netlify/lib/lessons.generated.mjs", import.meta.url),
  "// Generated by scripts/embed-lessons.mjs at build time. Do not edit.\nexport const LESSONS = " + JSON.stringify(out) + ";\n");
console.log("embedded lessons:", Object.keys(out).join(", "));
